import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"工具地图","description":"","frontmatter":{},"headers":[],"relativePath":"tools/index.md","filePath":"tools/index.md","lastUpdated":1785729506000}'),s={name:"tools/index.md"};function l(d,t,i,n,p,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="工具地图" tabindex="-1">工具地图 <a class="header-anchor" href="#工具地图" aria-label="Permalink to &quot;工具地图&quot;">​</a></h1><p>工具是链路上的零件，不是这件事的主角。所以这个板块放在 <a href="/method/">方法论</a> 和 <a href="/prompts/">Prompt 库</a> 的后面。</p><h2 id="本板块内容" tabindex="-1">本板块内容 <a class="header-anchor" href="#本板块内容" aria-label="Permalink to &quot;本板块内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>用于</th></tr></thead><tbody><tr><td><a href="/tools/landscape">全景对照表</a></td><td>搞清楚有哪几类工具、各自负责什么</td></tr><tr><td><a href="/tools/decision-tree">选型决策树</a></td><td>按预算和交付形态，快速定下用哪套</td></tr></tbody></table><h2 id="关于内容准确性的说明" tabindex="-1">关于内容准确性的说明 <a class="header-anchor" href="#关于内容准确性的说明" aria-label="Permalink to &quot;关于内容准确性的说明&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">这个板块的内容易变，请自行核实</p><p>AI 工具的迭代速度以周计。因此本站的处理原则是：</p><p><strong>写</strong>：工具的定位、擅长什么、不擅长什么、适合谁 —— 这类判断相对稳定。</p><p><strong>不写</strong>：价格、订阅档位、单次生成时长上限、分辨率上限、并发数、有没有某个具体功能 —— 这类信息随时变化，写死了反而误导。</p><p>看到需要具体数字的地方，请以官网为准。</p></div><h2 id="一个反常识的建议" tabindex="-1">一个反常识的建议 <a class="header-anchor" href="#一个反常识的建议" aria-label="Permalink to &quot;一个反常识的建议&quot;">​</a></h2><p><strong>别急着换工具。</strong></p><p>主流工具之间的能力差距，远小于使用者之间的差距。同一个模型，会拆分镜的人和不会的人，产出差一个量级。</p><p>判断标准：如果你的问题是「出来的东西很廉价」，那是 <a href="/prompts/structure">Prompt 结构</a> 的问题，换工具解决不了；如果你的问题是「这个效果这个工具根本做不出来」（比如需要精确控制的运镜、特定的时长），那才是工具的问题。</p><h2 id="待补充" tabindex="-1">待补充 <a class="header-anchor" href="#待补充" aria-label="Permalink to &quot;待补充&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">有意留白</p><ul><li><a href="/tools/reviews">单工具深度评测</a></li></ul></div><p>试了新工具？用 <a href="/templates/tool-review">工具评测模板</a> 记下来。</p>',13)])])}const u=a(s,[["render",l]]);export{m as __pageData,u as default};
